/**
 * THE MAILER, TESTED AGAINST A REAL SMTP CONVERSATION AND IN EVERY DIRECTION
 * THAT MATTERS MORE THAN DELIVERY — the ones where it must NOT send, and the
 * ones where it must not take a repair down with it.
 *
 * NO TEST HERE TOUCHES A REAL MAIL SERVER, AND NONE CARRIES A CREDENTIAL.
 * The fake server is `node:net` on 127.0.0.1 with an ephemeral port
 * (`listen(0)`; `node --test` runs files in parallel and a fixed port collides).
 * Every password in this file is generated by `randomUUID()` at run time, so no
 * secret-shaped literal is committed and the "this string is absent" assertions
 * are still exact.
 *
 * WHAT EACH MUTATION KILLED is recorded beside the test it belongs to. Each one
 * was applied to the source, compiled, run, its failures read off the runner's
 * output, reverted, and the revert proved byte-exact with sha256 — never with
 * `git diff`, which proves nothing about untracked files.
 *
 * TWO OF THEM SURVIVED and are written up where they belong (the header
 * injection test). A surviving mutation is data here, not an embarrassment to
 * be quietly re-run until it goes red.
 */

import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { createServer, connect as netConnect } from "node:net";
import type { AddressInfo, Server, Socket } from "node:net";
import test from "node:test";
import {
  DEFAULT_REPAIR_MAIL_TO,
  REPAIR_MAIL_ENV,
  SMTP_CODES,
  describeSmtpTarget,
  ehloCapabilities,
  messageIdFor,
  parseSmtpUrl,
  renderMailMessage,
  resolveRepairMailConfig,
  rfc5322Date,
  safeSubject,
  scrubUrlCredentials,
  sendRepairMail,
  supportsAuth,
  validAddress,
} from "./repair-mail.js";
import type { SmtpConnect, SmtpTarget, SmtpTransport } from "./repair-mail.js";

/* -------------------------------------------------------------------------
 * A fake SMTP server. Records every command line; replies are configurable so
 * the refusal arms are reachable without a broken real server.
 * ---------------------------------------------------------------------- */

interface FakeOptions {
  /** Capability lines after the first `250-`. Default: none. */
  readonly caps?: readonly string[];
  readonly rcptReply?: string;
  readonly bodyReply?: string;
  readonly authReply?: string;
  /** Accept the connection and then say nothing at all. */
  readonly mute?: boolean;
}

interface Fake {
  readonly port: number;
  /** Every command line the client sent, in order. */
  readonly commands: readonly string[];
  /** Each complete DATA payload, as received (still base64 in the body). */
  readonly messages: readonly string[];
  close: () => Promise<void>;
}

function startFakeSmtp(options: FakeOptions = {}): Promise<Fake> {
  const commands: string[] = [];
  const messages: string[] = [];
  const sockets = new Set<Socket>();
  const server: Server = createServer((socket) => {
    sockets.add(socket);
    socket.setEncoding("utf8");
    let buffer = "";
    let inData = false;
    let payload: string[] = [];
    if (!(options.mute ?? false)) socket.write("220 fake.invalid ESMTP ready\r\n");
    socket.on("data", (chunk: string) => {
      buffer += chunk;
      let at = buffer.indexOf("\n");
      while (at >= 0) {
        const line = buffer.slice(0, at).replace(/\r$/, "");
        buffer = buffer.slice(at + 1);
        at = buffer.indexOf("\n");
        if (inData) {
          if (line === ".") {
            inData = false;
            messages.push(payload.join("\n"));
            payload = [];
            socket.write(`${options.bodyReply ?? "250 2.0.0 Ok: queued as FAKE"}\r\n`);
          } else {
            payload.push(line);
          }
          continue;
        }
        commands.push(line);
        const upper = line.toUpperCase();
        if (upper.startsWith("EHLO")) {
          const caps = options.caps ?? [];
          const lines = ["250-fake.invalid greets you", ...caps.map((c) => `250-${c}`), "250 SIZE 10240000"];
          socket.write(`${lines.join("\r\n")}\r\n`);
        } else if (upper.startsWith("AUTH")) {
          socket.write(`${options.authReply ?? "235 2.7.0 Authentication successful"}\r\n`);
        } else if (upper.startsWith("MAIL FROM")) {
          socket.write("250 2.1.0 Ok\r\n");
        } else if (upper.startsWith("RCPT TO")) {
          socket.write(`${options.rcptReply ?? "250 2.1.5 Ok"}\r\n`);
        } else if (upper === "DATA") {
          inData = true;
          socket.write("354 End data with <CR><LF>.<CR><LF>\r\n");
        } else if (upper === "QUIT") {
          socket.write("221 2.0.0 Bye\r\n");
          socket.end();
        } else {
          socket.write("500 5.5.2 Unrecognised\r\n");
        }
      }
    });
    socket.on("error", () => { /* the client destroys the socket on close; not a fault */ });
    socket.on("close", () => { sockets.delete(socket); });
  });
  return new Promise<Fake>((resolve) => {
    server.listen(0, "127.0.0.1", () => {
      const address = server.address() as AddressInfo;
      resolve({
        port: address.port,
        commands,
        messages,
        close: () =>
          new Promise<void>((done) => {
            for (const socket of sockets) socket.destroy();
            server.close(() => { done(); });
          }),
      });
    });
  });
}

/** A transport over the fake server that reports whatever secrecy a test needs. */
function fakeConnect(port: number, secure: boolean): SmtpConnect {
  return async () =>
    new Promise<SmtpTransport>((resolve, reject) => {
      const socket = netConnect({ host: "127.0.0.1", port }, () => {
        resolve({ stream: socket, secure, upgrade: null, close: () => { socket.destroy(); } });
      });
      socket.once("error", reject);
    });
}

const BODY = "WHAT THE DASHBOARD DID WHILE YOU WERE AWAY\n\nIt fixed a price lookup — em dash on purpose.\n";

function envWith(url: string): NodeJS.ProcessEnv {
  return { [REPAIR_MAIL_ENV.smtpUrl]: url, [REPAIR_MAIL_ENV.mailTo]: "owner@example.com" };
}

/* -------------------------------------------------------------------------
 * Configuration
 * ---------------------------------------------------------------------- */

test("the SMTP URL is read into a target, with the submission ports as defaults", () => {
  const plain = parseSmtpUrl("smtp://mail.example.com");
  assert.equal(plain.ok, true);
  assert.deepEqual(plain.ok ? plain.target : null, { scheme: "smtp", host: "mail.example.com", port: 587, username: null, password: null });

  const implicit = parseSmtpUrl("smtps://mail.example.com");
  assert.equal(implicit.ok ? implicit.target.port : 0, 465);

  const explicit = parseSmtpUrl("smtps://mail.example.com:2525");
  assert.equal(explicit.ok ? explicit.target.port : 0, 2525);
});

test("a password with URL-reserved characters arrives DECODED, because that is what AUTH needs", () => {
  // Percent-encoded `a/b%c` — the decoded form is a second string that must
  // also never be printed. See the scrubbing test at the bottom of this file.
  const parsed = parseSmtpUrl("smtp://user%40host:a%2Fb%25c@mail.example.com:587");
  assert.equal(parsed.ok, true);
  assert.equal(parsed.ok ? parsed.target.password : null, "a/b%c");
  assert.equal(parsed.ok ? parsed.target.username : null, "user@host");
});

test("anything that is not smtp/smtps is refused, and the refusal never quotes the value", () => {
  const password = randomUUID();
  const parsed = parseSmtpUrl(`https://user:${password}@mail.example.com`);
  assert.equal(parsed.ok, false);
  assert.equal(parsed.ok ? "" : parsed.code, SMTP_CODES.badUrl);
  assert.equal((parsed.ok ? "" : parsed.detail).includes(password), false);
});

test("an empty URL is 'not configured', which is a state and not an error", () => {
  const config = resolveRepairMailConfig({});
  assert.equal(config.configured, false);
  assert.equal(config.to, DEFAULT_REPAIR_MAIL_TO, "the owner's address is the default recipient");
  assert.equal(config.from, DEFAULT_REPAIR_MAIL_TO, "the sender defaults to the recipient");
  assert.match(config.why, /no mail server is configured/);
  assert.match(config.why, /only copy of this report/);
});

test("describeSmtpTarget is the only renderable form of a target and carries neither name nor secret", () => {
  const password = randomUUID();
  const username = `account-${randomUUID()}`;
  const target: SmtpTarget = { scheme: "smtps", host: "mail.example.com", port: 465, username, password };
  const described = describeSmtpTarget(target);
  assert.equal(described.includes(password), false);
  assert.equal(described.includes(username), false);
  assert.match(described, /smtps:\/\/mail\.example\.com:465/);
  assert.match(described, /signing in/);
});

/* -------------------------------------------------------------------------
 * The message
 * ---------------------------------------------------------------------- */

test("EHLO capabilities are parsed off the continuation lines", () => {
  const caps = ehloCapabilities("250-hello\n250-STARTTLS\n250-AUTH PLAIN LOGIN\n250 SIZE 100");
  assert.deepEqual(caps, ["STARTTLS", "AUTH PLAIN LOGIN", "SIZE 100"]);
  assert.equal(supportsAuth(caps, "PLAIN"), true);
  assert.equal(supportsAuth(caps, "XOAUTH2"), false);
  assert.equal(supportsAuth(ehloCapabilities("250-hi\n250 AUTH=LOGIN"), "LOGIN"), true, "the old AUTH= form still counts");
});

/**
 * THREE MUTATIONS RUN HERE AND TWO OF THEM SURVIVED, WHICH IS DATA AND IS
 * RECORDED RATHER THAN TIDIED AWAY.
 *
 *   M1  `safeSubject`'s `[\r\n\t]+ → " "` replaced by the identity.
 *       **SURVIVED, 38/38 green.** The `[^\x20-\x7E]` filter on the next line
 *       already removes CR and LF, so the guard is not single-point.
 *   M1b the whole `flat` chain replaced by `const flat = raw`.
 *       **SURVIVED for this test** (it went red on two others, about the em
 *       dash and the ASCII subject). `collapsed`'s `\s{2,} → " "` still eats
 *       the CR LF pair — a THIRD overlapping stripper.
 *   M1c `Subject: ${safeSubject(message.subject)}` → `Subject: ${message.subject}`
 *       in `renderMailMessage`. **RED**, one test, this one, with the message
 *       *"the CR LF in the subject must not start a header line"*.
 *
 * So what this test actually measures is *"the subject goes through
 * `safeSubject` on the way into the header"*, and it cannot tell which of that
 * function's three overlapping rules is doing the work. Stated here because a
 * docblock claiming M1 went red would be exactly the defect this repository is
 * named for — and because the next person to simplify `safeSubject` needs to
 * know the suite will not catch them removing any single line of it.
 */
test("a subject cannot inject a header", () => {
  const message = renderMailMessage({
    from: "owner@example.com",
    to: "owner@example.com",
    subject: "Repair done\r\nBcc: somebody-else@example.com",
    body: BODY,
    date: new Date("2026-08-16T09:14:02.000Z"),
    messageId: "<x@example.com>",
  });
  const headers = (message.split("\r\n\r\n")[0] ?? "").split("\r\n");
  assert.equal(headers.some((line) => line.startsWith("Bcc:")), false, "the CR LF in the subject must not start a header line");
  assert.equal(headers.filter((line) => line.startsWith("Subject:")).length, 1);
  assert.equal(headers.filter((line) => line.includes("somebody-else@example.com")).length, 1, "the address survives as subject TEXT, on the Subject line and nowhere else");
  assert.match(message, /^Date: Sun, 16 Aug 2026 09:14:02 \+0000$/m);
  assert.match(message, /^Auto-Submitted: auto-generated$/m, "an unattended report must not draw an out-of-office reply");
});

test("the body travels as base64 so an em dash and a lone dot cannot break the transport", () => {
  const body = "line one — dashes\n.\nline three\n";
  const message = renderMailMessage({
    from: "a@example.com",
    to: "b@example.com",
    subject: "s",
    body,
    date: new Date(0),
    messageId: messageIdFor(new Date(0), "abcd1234", "a@example.com"),
  });
  const [, encoded = ""] = message.split("\r\n\r\n");
  assert.match(message, /^Content-Transfer-Encoding: base64$/m);
  assert.equal(Buffer.from(encoded.replace(/\r\n/g, ""), "base64").toString("utf8"), body);
  assert.equal(encoded.split("\r\n").some((line) => line === "."), false, "no line of the payload may be a bare dot");
  assert.match(messageIdFor(new Date(0), "abcd1234", "a@example.com"), /^<repair-1970-01-01T00-00-00-000Z-abcd1234@example\.com>$/);
});

test("addresses are checked before they reach a header", () => {
  assert.equal(validAddress("owner@example.com"), true);
  assert.equal(validAddress("owner@example.com\r\nBcc: x@y.zz"), false);
  assert.equal(validAddress("not-an-address"), false);
  assert.equal(rfc5322Date(new Date("2026-01-02T03:04:05Z")), "Fri, 02 Jan 2026 03:04:05 +0000");
  assert.equal(safeSubject("a—b   c"), "a-b c", "an em dash becomes a hyphen rather than an encoded word");
});

/* -------------------------------------------------------------------------
 * The conversation
 * ---------------------------------------------------------------------- */

/**
 * MUTATION RUN (the DATA terminator): `channel.write(\`${input.message}\r\n.\`)`
 * changed to `channel.write(input.message)`. RED, TWO TESTS — this one and the
 * AUTH one below, which also sends a body — with the measured detail *"the
 * conversation with the mail server failed: the server did not answer in
 * time"*. The fake server never saw the end of the payload, so the reply never
 * came and the send died on its deadline instead of reporting `MAIL_SENT`.
 */
test("a whole conversation reaches a server and the server gets the report", async (t) => {
  const fake = await startFakeSmtp();
  t.after(() => fake.close());
  const result = await sendRepairMail(
    { subject: "The dashboard fixed itself", body: BODY },
    { env: envWith(`smtp://127.0.0.1:${String(fake.port)}`), connect: fakeConnect(fake.port, false), timeoutMs: 5_000 },
  );
  assert.equal(result.ok, true, result.detail);
  assert.equal(result.code, SMTP_CODES.sent);
  assert.equal(fake.commands.some((c) => c.startsWith("MAIL FROM:<owner@example.com>")), true);
  assert.equal(fake.commands.some((c) => c.startsWith("RCPT TO:<owner@example.com>")), true);
  assert.equal(fake.commands.includes("QUIT"), true);
  const received = fake.messages[0] ?? "";
  const [, encoded = ""] = received.split("\n\n");
  assert.equal(Buffer.from(encoded.replace(/\n/g, ""), "base64").toString("utf8"), BODY, "the owner gets the report, byte for byte");
});

/**
 * THE ARM THAT MATTERS MOST, AND IT IS A REFUSAL.
 *
 * MUTATION RUN: the `if (!secure)` guard in `runSmtpConversation` disabled so
 * AUTH proceeds on a clear channel. RED, one test, this one. Without the guard
 * the password goes out as base64 — an encoding, not encryption — and the
 * fake server would have it.
 */
test("a password is NEVER sent over an unencrypted connection; the email is dropped instead", async (t) => {
  const fake = await startFakeSmtp({ caps: ["AUTH PLAIN LOGIN"] });
  t.after(() => fake.close());
  const password = randomUUID();
  const result = await sendRepairMail(
    { subject: "s", body: BODY },
    {
      env: envWith(`smtp://account:${password}@127.0.0.1:${String(fake.port)}`),
      connect: fakeConnect(fake.port, false),
      timeoutMs: 5_000,
    },
  );
  assert.equal(result.ok, false);
  assert.equal(result.code, SMTP_CODES.credentialOnPlaintext);
  assert.equal(fake.commands.some((c) => c.toUpperCase().startsWith("AUTH")), false, "not one AUTH byte on a clear channel");
  assert.equal(fake.messages.length, 0, "and nothing was delivered");
  assert.equal(JSON.stringify(result).includes(password), false);
});

test("AUTH PLAIN goes out once the connection reports itself encrypted, and the secret stays out of the result", async (t) => {
  const fake = await startFakeSmtp({ caps: ["AUTH PLAIN LOGIN"] });
  t.after(() => fake.close());
  const password = randomUUID();
  const result = await sendRepairMail(
    { subject: "s", body: BODY },
    {
      // The transport claims `secure: true` without TLS. That is the seam's
      // contract and the only way to exercise AUTH without a certificate; the
      // real `netSmtpConnect` sets it only after a verified handshake.
      env: envWith(`smtp://account:${password}@127.0.0.1:${String(fake.port)}`),
      connect: fakeConnect(fake.port, true),
      timeoutMs: 5_000,
    },
  );
  assert.equal(result.ok, true, result.detail);
  const auth = fake.commands.find((c) => c.toUpperCase().startsWith("AUTH PLAIN")) ?? "";
  assert.equal(Buffer.from(auth.slice("AUTH PLAIN ".length), "base64").toString("utf8"), `\0account\0${password}`);
  assert.equal(JSON.stringify(result).includes(password), false, "and it is still absent from everything this function returns");
});

test("a refused recipient is reported as a refused recipient, not as a generic failure", async (t) => {
  const fake = await startFakeSmtp({ rcptReply: "550 5.1.1 <owner@example.com>: Recipient address rejected" });
  t.after(() => fake.close());
  const result = await sendRepairMail(
    { subject: "s", body: BODY },
    { env: envWith(`smtp://127.0.0.1:${String(fake.port)}`), connect: fakeConnect(fake.port, false), timeoutMs: 5_000 },
  );
  assert.equal(result.ok, false);
  assert.equal(result.code, SMTP_CODES.rejected);
  assert.match(result.detail, /refused the recipient address/);
  assert.match(result.detail, /550/);
});

test("a server that accepts the connection and then says nothing times out rather than hanging", async (t) => {
  const fake = await startFakeSmtp({ mute: true });
  t.after(() => fake.close());
  const result = await sendRepairMail(
    { subject: "s", body: BODY },
    { env: envWith(`smtp://127.0.0.1:${String(fake.port)}`), connect: fakeConnect(fake.port, false), timeoutMs: 300 },
  );
  assert.equal(result.ok, false);
  assert.equal(result.code, SMTP_CODES.timedOut);
});

/* -------------------------------------------------------------------------
 * Fail open — the property the whole file exists for
 * ---------------------------------------------------------------------- */

/**
 * MUTATION RUN: the try/catch around `input.connect(...)` in
 * `runSmtpConversation` removed. RED, one test, this one. The call still
 * RESOLVED — the outer catch in `sendRepairMail` caught the throw — but with
 * `MAIL_SENDER_FAULT` instead of `SMTP_CONNECT_FAILED`, so it was the code
 * assertion that failed and not `doesNotReject`. That is exactly why this test
 * asserts the CODE: with two guards in the chain, "it did not throw" cannot
 * tell you which one was removed.
 */
test("a transport that throws is a named connection failure, not an exception", async () => {
  const exploding: SmtpConnect = () => { throw new Error("connect ECONNREFUSED 10.0.0.1:587"); };
  const result = await sendRepairMail({ subject: "s", body: BODY }, { env: envWith("smtp://mail.example.com"), connect: exploding });
  assert.equal(result.ok, false);
  assert.equal(result.code, SMTP_CODES.connectFailed);
  assert.match(result.detail, /could not reach the mail server/);
});

/**
 * MUTATION RUN: `throw error;` inserted as the first statement of the outer
 * catch in `sendRepairMail`, so the guard stops failing open. RED, one test,
 * this one, with node's *"Got unwanted rejection."* — which is exactly the
 * shape that would kill a repair at 3am.
 */
test("a bug inside the mailer itself comes back as a mail outcome and never as a rejection", async () => {
  const call = sendRepairMail(
    { subject: "s", body: BODY },
    {
      env: envWith("smtp://mail.example.com"),
      connect: fakeConnect(1, false),
      now: () => { throw new Error("the clock exploded"); },
    },
  );
  await assert.doesNotReject(call);
  const result = await call;
  assert.equal(result.ok, false);
  assert.equal(result.code, SMTP_CODES.unexpected);
  assert.match(result.detail, /the mail sender itself failed/);
});

/**
 * MUTATION RUN: `scrubUrlCredentials(outcome.detail, secrets)` in
 * `sendRepairMail`'s return replaced by `outcome.detail`. RED, one test, this
 * one, failing on *"the decoded password must not survive"*.
 */
test("a credential that arrives inside an error message is redacted on the way out, encoded and decoded", async () => {
  const raw = `${randomUUID()}/${randomUUID()}`;          // contains `/`
  const encoded = encodeURIComponent(raw);                // `%2F` in the URL
  const url = `smtp://account:${encoded}@mail.example.com:587`;
  const leaky: SmtpConnect = () => { throw new Error(`getaddrinfo ENOTFOUND while dialling ${url} (decoded secret ${raw})`); };
  const result = await sendRepairMail({ subject: "s", body: BODY }, { env: envWith(url), connect: leaky });
  assert.equal(result.ok, false);
  const everything = JSON.stringify(result);
  assert.equal(everything.includes(raw), false, "the decoded password must not survive");
  assert.equal(everything.includes(encoded), false, "nor the percent-encoded one");
  assert.match(everything, /\[redacted\]/);
});

test("the standalone scrubber redacts userinfo in any URL shape it meets", () => {
  const secret = randomUUID();
  assert.equal(scrubUrlCredentials(`see smtps://u:${secret}@h:465/x`), "see smtps://[redacted]@h:465/x");
  assert.equal(scrubUrlCredentials(`plain ${secret} text`, [secret]), "plain [redacted] text");
  assert.equal(scrubUrlCredentials("nothing to do here"), "nothing to do here");
});
